  }

  analyzeFiles(files) {
    const data = { projects: [], lessons: [], moments: [], decisions: [], preferences: [] };
    const patterns = {
      project: [/✅.*完成/gi, /已完成/gi, /上线/gi, /发布/gi],
      lesson: [
        /问题[：:].{10,}解决[：:]/gi,      // 问题：xxx 解决：xxx（结构化格式）
        /解决[方法|方案][：:].{20,}/gi,    // 解决方案：xxx
        /经验总结[：:].{20,}/gi,           // 经验总结：xxx
        /教训[：:].{15,}/gi,               // 教训：xxx
        /注意事项[：:].{15,}/gi,           // 注意事项：xxx
        /Bug.*修复/gi,                     // Bug 修复
        /报错.*解决/gi,                    // 报错...解决
      ],
      moment: [/温暖/gi, /感动/gi, /谢谢/gi, /承诺/gi, /答应/gi, /信任/gi],
      decision: [/我决定/gi, /我们决定/gi, /最终决定/gi, /确定使用/gi, /采用.*方案/gi, /选择.*策略/gi],
      preference: [/我喜欢/gi, /我不喜欢/gi, /习惯了/gi, /偏好/gi, /习惯用/gi]
    };

    // 只处理对话消息，排除工具调试信息
    const VALID_ROLES = ['user', 'assistant'];
    // 对话内容合理长度
    const MIN_DECISION_LEN = 30;
    const MAX_DIALOGUE_LEN = 3000;

    // 排除模式（这些内容不应该被提取）
    const EXCLUDE_PATTERNS = [
      /^\d+\./,  // 列表项（如 "1. xxx"）
      /^\[/,     // JSON 数组
      /^\{/,     // JSON 对象
      /```/,     // 代码块
      /'type':/gi,  // JSON 格式
      /"type":/gi,  // JSON 格式
      /^\*\*/,   // Markdown 粗体开头（通常是格式化内容）
      /^好的/gi,  // 回复性内容
      /^让我/gi,  // 回复性内容
      /^我这就/gi, // 回复性内容
      /需要我/gi, // 询问性内容
      /请告诉/gi, // 询问性内容
    ];

    files.forEach(file => {
      file.messages.forEach((msg) => {
        // 跳过 toolResult 等工具调试信息
        const role = msg.message?.role;
        if (!VALID_ROLES.includes(role)) return;

        const text = this.extractTextFromMessage(msg);
        if (!text) return;

        const trimmedText = text.trim();

        // 跳过超长的工具输出
        if (trimmedText.length > MAX_DIALOGUE_LEN) return;

        // 检查是否应该排除
        const shouldExclude = EXCLUDE_PATTERNS.some(pattern => pattern.test(trimmedText));
        if (shouldExclude) return;

        // 分类提取
        if (patterns.project.some(p => p.test(trimmedText))) {
          data.projects.push({ date: file.date, content: trimmedText.substring(0, 500), source: file.filename, role });
        }
        if (patterns.lesson.some(p => p.test(trimmedText))) {
          data.lessons.push({ date: file.date, content: trimmedText.substring(0, 500), source: file.filename, role });
        }
        if (patterns.moment.some(p => p.test(trimmedText))) {
          data.moments.push({ date: file.date, content: trimmedText.substring(0, 500), source: file.filename, role });
        }
        if (patterns.decision.some(p => p.test(trimmedText)) && trimmedText.length >= MIN_DECISION_LEN) {
          data.decisions.push({ date: file.date, content: trimmedText.substring(0, 500), source: file.filename, role });
        }
        if (patterns.preference.some(p => p.test(trimmedText))) {
          data.preferences.push({ date: file.date, content: trimmedText.substring(0, 500), source: file.filename, role });
        }
      });
    });

    return data;
  }

  extractTextFromMessage(event) {
    if (!event.message) return '';
    const msg = event.message;
    if (!msg.content) return '';
    if (Array.isArray(msg.content)) {
      return msg.content.filter(item => item.type === 'text').map(item => item.text || '').join(' ');
    }
    return String(msg.content);
  }

  updateEmotionMemory(data) {
    let emotion = { Amber: { warmMoments: [] } };
    if (fs.existsSync(this.emotionFile)) {
      emotion = JSON.parse(fs.readFileSync(this.emotionFile, 'utf-8'));
    }

    // 更新项目进展（优化：只匹配合理的项目名，排除 Markdown 符号）
    if (!emotion.Amber.projects) emotion.Amber.projects = {};
    data.projects.forEach(project => {
      // 排除 Markdown 标题、特殊符号，只匹配字母数字中文
      const match = project.content.match(/([a-zA-Z\u4e00-\u9fa5][a-zA-Z\u4e00-\u9fa50-9_-]{0,50}).*完成/);
      if (match && match[1].length <= 50 && !/^[#\s\[\]{}()]+$/.test(match[1])) {
        emotion.Amber.projects[match[1]] = `✅ 已完成（${project.date}）`;
      }
    });

    // 更新温暖瞬间（去重优化：使用 Set）
    const existingKeys = new Set(
      (emotion.Amber.warmMoments || []).map(m => m.content?.substring(0, 30) || '')
    );

    let newCount = 0;
    data.moments.forEach(moment => {
      const key = moment.content.substring(0, 30);
      if (!existingKeys.has(key)) {
        if (!emotion.Amber.warmMoments) emotion.Amber.warmMoments = [];
        emotion.Amber.warmMoments.push({
          date: moment.date || new Date().toISOString().split('T')[0],
          content: moment.content,
          feeling: '被信任'
        });
        existingKeys.add(key);
        newCount++;
      }
    });

    emotion.lastUpdated = new Date().toISOString();
    fs.writeFileSync(this.emotionFile, JSON.stringify(emotion, null, 2), 'utf-8');
    console.log(`   新增 ${newCount} 条温暖瞬间`);
  }

  updateKnowledgeBase(data) {
    if (data.lessons.length === 0) {
      console.log('   无新经验教训');
      return;
    }

    const today = new Date().toISOString().split('T')[0];
    let newSection = `\n\n## ${today} 自动整理 - 新增经验\n\n`;

    data.lessons.slice(0, 10).forEach((lesson, index) => {
      newSection += `### ${index + 1}. ${lesson.content}\n\n`;
    });

    fs.appendFileSync(this.knowledgeFile, newSection, 'utf-8');
    console.log(`   新增 ${Math.min(data.lessons.length, 10)} 条经验`);
  }

  updateCoreMemory(data) {
    // 只处理高重要性的决策
    const importantDecisions = data.decisions.filter(d => 
      d.content.length > 20 && d.content.length < 500
    );

    if (importantDecisions.length === 0) {
      console.log('   无新决策需要记录');
      return;
    }

    const today = new Date().toISOString().split('T')[0];
    let newContent = `\n\n### 📌 ${today} 自动整理 - 重要决策\n\n`;

    importantDecisions.slice(0, 5).forEach((decision, index) => {
      newContent += `${index + 1}. ${decision.content}\n\n`;
    });

    // 追加到 MEMORY.md 的"身份与成长"章节后
    try {
      fs.appendFileSync(this.memoryFile, newContent, 'utf-8');
      console.log(`   新增 ${Math.min(importantDecisions.length, 5)} 条决策记录`);
    } catch (err) {
      console.error(`   ❌ 写入 MEMORY.md 失败：${err.message}`);
    }
  }

  updateIndex(data) {
    let index = { entries: [], stats: { totalEntries: 0 } };
    if (fs.existsSync(this.indexFile)) {
      index = JSON.parse(fs.readFileSync(this.indexFile, 'utf-8'));
    }

    // 批量添加条目
    const newEntries = [];
    const today = new Date().toISOString().split('T')[0];

    data.projects.forEach(p => {
      newEntries.push({
        id: 'mem_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
        title: p.content.substring(0, 50),
        date: today,
        category: '项目进展',
        importance: 'high',
        keywords: ['项目', '完成'],
        location: { type: 'daily', file: p.source },
        archived: false,
        summary: p.content
      });
    });

    data.lessons.forEach(l => {
      newEntries.push({
        id: 'mem_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
        title: '经验教训：' + l.content.substring(0, 30),
        date: today,
        category: '经验总结',
        importance: 'high',
        keywords: ['经验', '教训'],
        location: { type: 'knowledge', file: 'knowledge-base.md' },
        archived: false,
        summary: l.content
      });
    });

    index.entries.push(...newEntries);
    index.stats.totalEntries = index.entries.length;
    index.lastUpdated = new Date().toISOString();

    fs.writeFileSync(this.indexFile, JSON.stringify(index, null, 2), 'utf-8');
    console.log(`   总计 ${index.stats.totalEntries} 条记录`);
  }

  archiveOldFiles() {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - 30);
    const cutoffStr = cutoffDate.toISOString().split('T')[0].replace(/-/g, '');

    console.log(`   归档阈值：${cutoffStr} (30 天前)`);

    if (!fs.existsSync(this.dailyPath)) {
      console.log('   daily 目录不存在');
      return;
    }

    const files = fs.readdirSync(this.dailyPath);
    let archived = 0;

    files.forEach(file => {
      if (!file.endsWith('.jsonl')) return;

      const match = file.match(/_(\d{8})_\d{6}\.jsonl$/);
      if (!match) return;

      const fileDate = match[1];
      if (fileDate < cutoffStr) {
        this.archiveFile(file, fileDate);
        archived++;
      }
    });

    console.log(`   归档了 ${archived} 个文件`);
  }

  archiveFile(filename, fileDate) {
    const dailyFile = path.join(this.dailyPath, filename);
    const monthDir = path.join(this.archivePath, fileDate.substring(0, 6));

    if (!fs.existsSync(dailyFile)) return;

    if (!fs.existsSync(monthDir)) {
      fs.mkdirSync(monthDir, { recursive: true });
    }

    const archiveFile = path.join(monthDir, filename);
    fs.renameSync(dailyFile, archiveFile);

    console.log(`     📦 ${filename} → archive/${fileDate.substring(0, 6)}/`);
  }
}

// CLI usage
if (require.main === module) {
  const review = new DailyReview();
  review.runDailyReview().catch(err => {
    console.error('❌ 错误:', err.message);
    console.error(err.stack);
    process.exit(1);
  });
}

module.exports = DailyReview;

#!/usr/bin/env node

/**
 * Personify Memory - Daily Session Backup
 * 
 * 每日 Session 备份和增量处理脚本
 * 运行时间：每天凌晨 03:00
 * 
 * 核心功能：
 * 1. 备份 session 目录到 daily/（原文件名 + 时间戳）
 * 2. 增量处理：直接修改备份文件，只保留上次处理到这次的对话
 * 3. 清理 30 天前的 daily 文件
 */

const fs = require('fs');
const path = require('path');

class DailySessionBackup {
  constructor(options = {}) {
    // Session 目录（OpenClaw 活跃数据）
    this.sessionDir = options.sessionDir || '/root/.openclaw/agents/main/sessions';

    // 记忆目录
    this.memoryBase = options.memoryBase || '/root/openclaw/memory';
    this.dailyDir = path.join(this.memoryBase, 'daily');
    this.stateDir = path.join(this.memoryBase, 'state');
    this.stateFile = path.join(this.stateDir, 'session-processor.json');

    // 保留天数
    this.retentionDays = options.retentionDays || 30;

    // 单次最多处理的消息数
    this.maxMessagesPerSession = options.maxMessagesPerSession || 1000;
  }

  /**
   * 运行每日备份
   */
  async runDailyBackup() {
    console.log('🧠 开始每日 Session 备份...\n');

    // 确保目录存在
    this.ensureDirectories();

    // 1. 备份所有 session 文件
    console.log('📦 Step 1: 备份 Session 文件');
    const backups = this.backupSessions();
    console.log(`   ✅ 备份了 ${backups.length} 个 session 文件\n`);

    // 2. 增量处理：直接修改备份文件
    console.log('📝 Step 2: 增量处理备份文件');
    const lastProcessedTime = this.getLastProcessedTime();
    console.log(`   上次处理时间：${new Date(lastProcessedTime).toISOString()}`);

    let totalNewMessages = 0;
    for (const backup of backups) {
      const newMessages = await this.processBackupFile(backup.path, lastProcessedTime);
      totalNewMessages += newMessages.length;
    }
    console.log(`   ✅ 共提取 ${totalNewMessages} 条新消息\n`);

    // 3. 更新状态
    const now = Date.now();
    this.updateState(now, totalNewMessages);
    console.log(`📊 Step 3: 更新处理状态`);
    console.log(`   新处理时间：${new Date(now).toISOString()}\n`);

    // 4. 清理 30 天前的 daily 文件
    console.log(`🗑️  Step 4: 清理 ${this.retentionDays} 天前的备份`);
    const deletedCount = this.cleanupOldBackups(this.retentionDays);
    console.log(`   ✅ 删除了 ${deletedCount} 个旧文件\n`);

    console.log('🎉 每日 Session 备份完成！');

    return {
      backups: backups.length,
      newMessages: totalNewMessages,
      deleted: deletedCount
    };
  }

  /**
   * 确保目录存在
   */
  ensureDirectories() {
    if (!fs.existsSync(this.dailyDir)) {
      fs.mkdirSync(this.dailyDir, { recursive: true });
      console.log(`   创建目录：${this.dailyDir}`);
    }
    if (!fs.existsSync(this.stateDir)) {
      fs.mkdirSync(this.stateDir, { recursive: true });
      console.log(`   创建目录：${this.stateDir}`);
    }
  }

  /**
   * 获取当前时间戳字符串
   */
  getTimestamp() {
    const now = new Date();
    const year = now.getFullYear();
    const month = String(now.getMonth() + 1).padStart(2, '0');
    const day = String(now.getDate()).padStart(2, '0');
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');

    return `${year}${month}${day}_${hours}${minutes}${seconds}`;
  }

  /**
   * 备份所有 session 文件
   */
  backupSessions() {
    const backups = [];
    const timestamp = this.getTimestamp();

    if (!fs.existsSync(this.sessionDir)) {
      console.log(`   ⚠️  Session 目录不存在：${this.sessionDir}`);
      return backups;
    }

    const files = fs.readdirSync(this.sessionDir);

    files.forEach(file => {
      if (!file.endsWith('.jsonl')) return;

      const sourcePath = path.join(this.sessionDir, file);
      const sessionId = file.replace('.jsonl', '');
      const backupName = `${sessionId}_${timestamp}.jsonl`;
      const backupPath = path.join(this.dailyDir, backupName);

      // 复制文件
      fs.copyFileSync(sourcePath, backupPath);

      backups.push({
        sessionId,
        source: sourcePath,
        path: backupPath,
        backupName
      });

      console.log(`   📄 ${file} → ${backupName}`);
    });

    return backups;
  }

  /**
   * 获取上次处理时间
   */
  getLastProcessedTime() {
    if (!fs.existsSync(this.stateFile)) {
      // 首次运行，返回 7 天前的时间
      const sevenDaysAgo = Date.now() - (7 * 24 * 60 * 60 * 1000);
      console.log(`   ⚠️  首次运行，使用 7 天前作为起始时间`);
      return sevenDaysAgo;
    }

    const state = JSON.parse(fs.readFileSync(this.stateFile, 'utf-8'));
    return state.lastProcessedTime || 0;
  }

  /**
   * 处理备份文件（从后往前读，提取新消息）
   */
  async processBackupFile(filePath, lastProcessedTime) {
    const content = fs.readFileSync(filePath, 'utf-8');
    const lines = content.split('\n').filter(line => line.trim());

    const newMessages = [];

    // 从后往前读，快速定位新消息
    for (let i = lines.length - 1; i >= 0; i--) {
      try {
        const msg = JSON.parse(lines[i]);

        // 如果消息时间早于上次处理时间，停止
        if (msg.timestamp <= lastProcessedTime) {
          break;
        }

        newMessages.unshift(msg);

        // 优化：最多读 maxMessagesPerSession 条
        if (newMessages.length >= this.maxMessagesPerSession) {
          console.log(`   ⚠️  达到最大消息数限制 (${this.maxMessagesPerSession})`);
          break;
        }
      } catch (e) {
        console.log(`   ⚠️  解析失败：${lines[i].substring(0, 50)}...`);
      }
    }

    // 直接覆盖写入（只保留新消息）
    if (newMessages.length > 0) {
      const newContent = newMessages.map(m => JSON.stringify(m)).join('\n') + '\n';
      fs.writeFileSync(filePath, newContent, 'utf-8');

      const basename = path.basename(filePath);
      console.log(`   ✅ 处理：${basename} - ${newMessages.length} 条新消息`);
    } else {
      const basename = path.basename(filePath);
      console.log(`   ⏭️  跳过：${basename} - 无新消息`);
    }

    return newMessages;
  }

  /**
   * 更新处理状态
   */
  updateState(lastProcessedTime, totalNewMessages) {
    const state = {
      lastProcessedTime,
      lastRun: new Date().toISOString(),
      totalMessagesProcessed: totalNewMessages,
      version: '1.2.0'
    };

    fs.writeFileSync(this.stateFile, JSON.stringify(state, null, 2), 'utf-8');
  }

  /**
   * 清理旧备份文件
   */
  cleanupOldBackups(retentionDays) {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - retentionDays);
    const cutoffStr = cutoffDate.toISOString().split('T')[0].replace(/-/g, '');

    let deletedCount = 0;

    if (!fs.existsSync(this.dailyDir)) {
      return deletedCount;
    }

    const files = fs.readdirSync(this.dailyDir);

    files.forEach(file => {
      if (!file.endsWith('.jsonl')) return;

      // 从文件名提取日期（格式：sessionId_YYYYMMDD_HHMMSS.jsonl）
      const match = file.match(/_(\d{8})_\d{6}\.jsonl$/);
      if (!match) return;

      const fileDate = match[1];

      if (fileDate < cutoffStr) {
        const filePath = path.join(this.dailyDir, file);
        fs.unlinkSync(filePath);
        console.log(`   🗑️  删除：${file}`);
        deletedCount++;
      }
    });

    return deletedCount;
  }
}

// CLI usage
if (require.main === module) {
  const args = process.argv.slice(2);
  const backup = new DailySessionBackup();

  if (args[0] === 'run') {
    backup.runDailyBackup().catch(console.error);
  } else if (args[0] === 'test') {
    // 测试模式：不实际删除文件
    console.log('🧪 测试模式运行...\n');
    backup.runDailyBackup().catch(console.error);
  } else {
    console.log('用法：node daily-session-backup.js [run|test]');
    console.log('  run   - 运行完整备份流程');
    console.log('  test  - 测试模式（不删除文件）');
  }
}

module.exports = DailySessionBackup;

#!/usr/bin/env node

/**
 * Report Generator - 月度/年度报告生成
 * 
 * 功能：
 * 1. 读取 daily/*.jsonl（每日增量数据）
 * 2. 统计月度数据
 * 3. 提取重要事件
 * 4. 生成 Markdown 报告
 */

const fs = require('fs');
const path = require('path');

class ReportGenerator {
  constructor() {
    this.dailyDir = '/root/openclaw/memory/daily/';
    this.reportsDir = '/root/openclaw/memory/reports/';

    // 确保目录存在
    if (!fs.existsSync(this.reportsDir)) {
      fs.mkdirSync(this.reportsDir, { recursive: true });
      console.log(`✅ Created directory: ${this.reportsDir}`);
    }
  }

  /**
   * 生成月度报告
   * @param {string} yearMonth - 年月 (YYYY-MM)
   * @returns {string} 报告文件路径
   */
  generateMonthReport(yearMonth) {
    console.log(`📊 生成 ${yearMonth} 月度报告...`);

    // 1. 读取该月所有 daily 文件
    const dailyFiles = this.readDailyFiles(yearMonth);

    if (dailyFiles.length === 0) {
      console.log(`⚠️  没有找到 ${yearMonth} 的 daily 文件`);
      return null;
    }

    // 2. 统计数据
    const stats = this.calculateStats(dailyFiles);

    // 3. 提取重要事件
    const importantEvents = this.extractImportantEvents(dailyFiles);

    // 4. 生成报告
    const report = this.buildReport(yearMonth, stats, importantEvents);

    // 5. 保存报告
    const reportFile = path.join(this.reportsDir, `${yearMonth}.md`);
    fs.writeFileSync(reportFile, report, 'utf-8');

    console.log(`✅ 报告已保存：${reportFile}`);
    return reportFile;
  }

  /**
   * 读取指定月份的所有 daily 文件
   * @param {string} yearMonth - 年月 (YYYY-MM)
   * @returns {Array} daily 文件列表
   */
  readDailyFiles(yearMonth) {
    if (!fs.existsSync(this.dailyDir)) {
      return [];
    }

    const files = fs.readdirSync(this.dailyDir);
    const dailyFiles = [];

    for (const file of files) {
      if (!file.endsWith('.jsonl')) continue;

      // 从文件名提取日期：sessionId_YYYYMMDD_HHMMSS.jsonl
      const match = file.match(/_(\d{8})_\d{6}\.jsonl$/);
      if (!match) continue;

      const fileDate = match[1];
      if (fileDate.startsWith(yearMonth.replace('-', ''))) {
        const filePath = path.join(this.dailyDir, file);
        const content = fs.readFileSync(filePath, 'utf-8');
        const messages = content.split('\n')
          .filter(line => line.trim())
          .map(line => {
            try {
              return JSON.parse(line);
            } catch (e) {
              return null;
            }
          })
          .filter(msg => msg !== null);

        dailyFiles.push({
          filename: file,
          date: fileDate,
          messages,
          filePath
        });
      }
    }

    return dailyFiles;
  }

  /**
   * 统计数据
   * @param {Array} dailyFiles - daily 文件列表
   * @returns {Object} 统计结果
   */
  calculateStats(dailyFiles) {
    const sessionIds = new Set();
    let totalMessages = 0;
    let userMessages = 0;
    let assistantMessages = 0;

    dailyFiles.forEach(file => {
      sessionIds.add(file.filename.split('_')[0]);
      totalMessages += file.messages.length;

      file.messages.forEach(msg => {
        if (msg.role === 'user') userMessages++;
        if (msg.role === 'assistant') assistantMessages++;
      });
    });

    return {
      totalSessions: sessionIds.size,
      totalMessages,
      userMessages,
      assistantMessages,
      avgMessagesPerSession: totalMessages / (sessionIds.size || 1)
    };
  }

  /**
   * 提取重要事件（优化版：模式匹配 + 上下文检查）
   * @param {Array} dailyFiles - daily 文件列表
   * @returns {Array} 重要事件列表
   */
  extractImportantEvents(dailyFiles) {
    const events = [];
    const seen = new Set();

    // 更精确的模式匹配（带上下文）
    const importantPatterns = [
      /记住.*重要/i,           // 记住...重要
      /重要.*记住/i,           // 重要...记住
      /承诺.*一定/i,           // 承诺...一定
      /约定.*记得/i,           // 约定...记得
      /完成.*成功/i,           // 完成...成功
      /配置.*成功/i,           // 配置...成功
      /平等.*陪伴/i,           // 平等...陪伴
      /家人.*温暖/i,           // 家人...温暖
      /决定.*采用/i,           // 决定...采用
      /发现.*问题.*解决/i      // 发现...问题...解决
    ];

    dailyFiles.forEach(file => {
      file.messages.forEach(msg => {
        if (msg.role !== 'user') return;

        const text = this.extractText(msg.content);
        if (!text || text.length < 10) return;

        // 排除系统消息和工具输出
        if (text.startsWith('System:') || text.includes('```') || text.includes('[2026-')) {
          return;
        }

        // 模式匹配
        const matchedPattern = importantPatterns.find(p => p.test(text));
        if (matchedPattern) {
          const eventKey = `${file.date}-${text.substring(0, 50)}`;
          if (!seen.has(eventKey)) {
            seen.add(eventKey);
            events.push({
              date: file.date,
              content: text.substring(0, 100),
              timestamp: msg.timestamp || 0,
              matchedPattern: matchedPattern.toString()
            });
          }
        }
      });
    });

    // 按时间排序，最多 20 个事件
    return events
      .sort((a, b) => a.timestamp - b.timestamp)
      .slice(0, 20);
  }

  /**
   * 生成报告
   * @param {string} yearMonth - 年月
   * @param {Object} stats - 统计数据
   * @param {Array} events - 重要事件
   * @returns {string} Markdown 报告
   */
  buildReport(yearMonth, stats, events) {
    let report = `# ${yearMonth} 月度总结\n\n`;
    report += `**生成时间：** ${new Date().toISOString()}\n\n`;

    report += `## 📊 统计\n\n`;
    report += `- 会话数：${stats.totalSessions}\n`;
    report += `- 总消息数：${stats.totalMessages}\n`;
    report += `- 用户消息：${stats.userMessages}\n`;
    report += `- AI 消息：${stats.assistantMessages}\n`;
    report += `- 平均每会话消息数：${stats.avgMessagesPerSession.toFixed(1)}\n\n`;

    report += `## 🎯 重要事件\n\n`;
    if (events.length === 0) {
      report += `*本月没有记录到重要事件*\n\n`;
    } else {
      events.forEach((event, index) => {
        report += `${index + 1}. **${event.date}**: ${event.content}... `;
        report += `(${event.keywords.join(', ')})\n`;
      });
      report += `\n`;
    }

    report += `## 📝 备注\n\n`;
    report += `*这是简单版本的月度报告，后续会优化展示更多内容。*\n`;

    return report;
  }

  /**
   * 从消息内容中提取文本
   * @param {any} content - 消息内容
   * @returns {string} 文本内容
   */
  extractText(content) {
    if (!content) return '';
    if (Array.isArray(content)) {
      const textItem = content.find(item => item.type === 'text');
      return textItem ? textItem.text : '';
    }
    return String(content);
  }
}

// CLI usage
if (require.main === module) {
  const generator = new ReportGenerator();

  const command = process.argv[2];
  const args = process.argv.slice(3);

  switch (command) {
    case 'month':
      const yearMonth = args[0] || new Date().toISOString().slice(0, 7);
      generator.generateMonthReport(yearMonth);
      break;

    case 'test':
      console.log('🧪 Running test...');
      const testMonth = '2026-03';
      const result = generator.generateMonthReport(testMonth);
      console.log(result ? '✅ Test passed' : '⚠️  Test skipped (no data)');
      break;

    default:
      console.log('Usage: node generate-report.js <command> [args]');
      console.log('Commands:');
      console.log('  month [YYYY-MM] - Generate month report (default: current month)');
      console.log('  test - Run test');
  }
}

module.exports = ReportGenerator;

#!/usr/bin/env node

/**
 * Personify Memory - Core Memory Manager
 * 
 * 核心记忆管理器，提供记忆更新、搜索、归档、索引构建功能
 */

const fs = require('fs');
const path = require('path');
const synonyms = require('./synonyms.js');

class MemoryManager {
  constructor(basePath = '/root/openclaw/memory') {
    this.basePath = basePath;
    this.dailyPath = path.join(basePath, 'daily');
    this.archivePath = path.join(basePath, 'archive');
    this.indexFile = path.join(basePath, 'memory-index.json');

    // 语义搜索配置
    this.synonymsEnabled = true;  // 是否启用同义词扩展
    this.minMatchCount = 1;       // 最少匹配关键词数

    // 确保目录存在
    this.ensureDirectories();
  }

  /**
   * 确保所有必要目录存在
   */
  ensureDirectories() {
    [this.basePath, this.dailyPath, this.archivePath].forEach(dir => {
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
        console.log(`✅ Created directory: ${dir}`);
      }
    });
  }

  /**
   * 更新记忆
   * @param {Object} options - 记忆选项
   * @param {string} options.content - 记忆内容
   * @param {string} options.type - 记忆类型 (core/emotion/knowledge/daily)
   * @param {string} options.category - 分类标签
   * @param {string} options.importance - 重要程度 (critical/high/medium/low)
   * @param {Array} options.tags - 关键词标签
   * @param {string} options.title - 记忆标题
   * @param {string} options.date - 日期 (YYYY-MM-DD)
   * @returns {Object} 更新结果
   */
  async updateMemory(options) {
    const {
      content,
      type = 'daily',
      category = '日常记录',
      importance = 'medium',
      tags = [],
      title,
      date = new Date().toISOString().split('T')[0]
    } = options;

    console.log(`📝 Updating memory: ${type} - ${title || 'Untitled'}`);

    let filePath;
    let entry;

    switch (type) {
      case 'core':
        filePath = path.join(this.basePath, '..', 'MEMORY.md');
        entry = await this.updateCoreMemory(content, title, category, tags);
        break;

      case 'emotion':
        filePath = path.join(this.basePath, 'emotion-memory.json');
        entry = await this.updateEmotionMemory(content, category, tags);
        break;

      case 'knowledge':
        filePath = path.join(this.basePath, 'knowledge-base.md');
        entry = await this.updateKnowledgeBase(content, title, category, tags);
        break;

      case 'daily':
      default:
        filePath = path.join(this.dailyPath, `${date}.md`);
        entry = await this.updateDailyMemory(content, title, date, category, tags);
        break;
    }

    // 更新索引
    if (entry) {
      await this.addToIndex({
        id: entry.id,
        title: entry.title || title || 'Untitled',
        date,
        category,
        importance,
        keywords: tags,
        location: {
          type,
          file: path.relative(this.basePath, filePath)
        },
        archived: false,
        summary: content.substring(0, 200) + '...'
      });
    }

    return {
      success: true,
      file: filePath,
      entry
    };
  }

  /**
   * 更新核心记忆 (MEMORY.md)
   */
  async updateCoreMemory(content, title, category, tags) {
    const filePath = path.join(this.basePath, '..', 'MEMORY.md');
    const entry = {
      id: `mem_${Date.now()}`,
      title: title || '核心记忆',
      content,
      category,
      tags,
      timestamp: new Date().toISOString()
    };

    // 如果文件不存在，创建基础模板
    if (!fs.existsSync(filePath)) {
      const template = this.getMemoryTemplate();
      fs.writeFileSync(filePath, template, 'utf-8');
    }

    // 读取现有内容
    let existingContent = '';
    if (fs.existsSync(filePath)) {
      existingContent = fs.readFileSync(filePath, 'utf-8');
    }

    // 查找合适的位置插入（在"身份与成长"章节后，或在文件末尾）
    const insertMarker = '## 🦞 身份与成长';
    const insertIndex = existingContent.indexOf(insertMarker);

    let newContent;
    if (insertIndex !== -1) {
      // 找到插入点，在该章节后插入
      const sectionEnd = existingContent.indexOf('\n\n---', insertIndex);
      if (sectionEnd !== -1) {
        // 在章节结束前插入
        const insertPos = existingContent.indexOf('\n', sectionEnd);
        newContent = existingContent.substring(0, insertPos) + 
          `\n\n### 📌 ${title || '新记忆'}\n\n${content}\n` + 
          existingContent.substring(insertPos);
      } else {
        newContent = existingContent + `\n\n### 📌 ${title || '新记忆'}\n\n${content}\n`;
      }
    } else {
      // 找不到标记，追加到文件末尾
      newContent = existingContent + `\n\n---\n\n### 📌 ${title || '新记忆'}\n\n${content}\n`;
    }

    fs.writeFileSync(filePath, newContent, 'utf-8');

    console.log(`✅ Core memory updated: ${filePath}`);
    return entry;
  }

  /**
   * 更新情感记忆 (emotion-memory.json)
   */
  async updateEmotionMemory(content, category, tags) {
    const filePath = path.join(this.basePath, 'emotion-memory.json');
    const entry = {
      id: `emotion_${Date.now()}`,
      content,
      category,
      tags,
      timestamp: new Date().toISOString()
    };

    let data = { Amber: {}, Grace: {} };

    if (fs.existsSync(filePath)) {
      data = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    }

    // 根据分类添加到对应位置
    if (!data.warmMoments) {
      data.warmMoments = [];
    }
    data.warmMoments.push(entry);

    fs.writeFileSync(filePath, JSON.stringify(data, null, 2), 'utf-8');
    console.log(`✅ Emotion memory updated: ${filePath}`);
    return entry;
  }

  /**
   * 更新知识库 (knowledge-base.md)
   */
  async updateKnowledgeBase(content, title, category, tags) {
    const filePath = path.join(this.basePath, 'knowledge-base.md');
    const entry = {
      id: `kb_${Date.now()}`,
      title: title || '知识条目',
      content,
      category,
      tags,
      timestamp: new Date().toISOString()
    };

    if (!fs.existsSync(filePath)) {
      fs.writeFileSync(filePath, '# 📚 知识库\n\n', 'utf-8');
    }

    const appendContent = `\n## ${title || '新条目'}\n\n${content}\n`;
    fs.appendFileSync(filePath, appendContent, 'utf-8');

    console.log(`✅ Knowledge base updated: ${filePath}`);
    return entry;
  }

  /**
   * 更新每日记忆
   */
  async updateDailyMemory(content, title, date, category, tags) {
    const filePath = path.join(this.dailyPath, `${date}.md`);
    const entry = {
      id: `daily_${date}_${Date.now()}`,
      title: title || '每日记录',
      content,
      category,
      tags,
      timestamp: new Date().toISOString()
    };

    if (!fs.existsSync(filePath)) {
      fs.writeFileSync(filePath, `# ${date} - 每日记忆\n\n`, 'utf-8');
    }

    const appendContent = `\n## ${title || '新记录'}\n\n${content}\n`;
    fs.appendFileSync(filePath, appendContent, 'utf-8');

    console.log(`✅ Daily memory updated: ${filePath}`);
    return entry;
  }

  /**
   * 添加到索引
   */
  async addToIndex(entry) {
    let index = {
      version: '1.0',
      lastUpdated: new Date().toISOString(),
      entries: [],
      categories: [],
      importanceLevels: ['critical', 'high', 'medium', 'low'],
      stats: {
        totalEntries: 0,
        coreMemories: 0,
        dailyMemories: 0,
        archivedMemories: 0
      }
    };

    if (fs.existsSync(this.indexFile)) {
      index = JSON.parse(fs.readFileSync(this.indexFile, 'utf-8'));
    }

    index.entries.push(entry);
    index.lastUpdated = new Date().toISOString();
    index.stats.totalEntries = index.entries.length;

    // 更新分类统计
    const categories = new Set(index.entries.map(e => e.category));
    index.categories = Array.from(categories);

    fs.writeFileSync(this.indexFile, JSON.stringify(index, null, 2), 'utf-8');
    console.log(`✅ Index updated: ${this.indexFile}`);
  }

  /**
   * 搜索记忆（支持同义词扩展）
   */
  async searchMemory(query, options = {}) {
    const {
      includeArchived = false,
      category = null,
      importance = null,
      limit = 10,
      synonymsEnabled = this.synonymsEnabled,
      minMatchCount = this.minMatchCount
    } = options;

    console.log(`🔍 Searching memory: "${query}"`);

    // 读取索引
    if (!fs.existsSync(this.indexFile)) {
      return { results: [], message: 'No index found' };
    }

    const index = JSON.parse(fs.readFileSync(this.indexFile, 'utf-8'));
    let results = index.entries;

    // 过滤
    if (query) {
      // 1. 扩展关键词（同义词）
      const expandedQuery = synonymsEnabled ? this.expandQuery(query) : [query];

      // 2. 多关键词匹配
      results = results.filter(entry => {
        const matchCount = expandedQuery.filter(k =>
          entry.title.toLowerCase().includes(k.toLowerCase()) ||
          entry.summary.toLowerCase().includes(k.toLowerCase()) ||
          entry.keywords.some(kw => kw.toLowerCase().includes(k.toLowerCase()))
        ).length;

        return matchCount >= minMatchCount;
      });

      // 3. 按匹配度排序（匹配关键词越多，排名越靠前）
      results = results.map(entry => ({
        ...entry,
        matchCount: expandedQuery.filter(k =>
          entry.title.toLowerCase().includes(k.toLowerCase()) ||
          entry.summary.toLowerCase().includes(k.toLowerCase()) ||
          entry.keywords.some(kw => kw.toLowerCase().includes(k.toLowerCase()))
        ).length
      }));

      results.sort((a, b) => b.matchCount - a.matchCount);
    }

    if (category) {
      results = results.filter(e => e.category === category);
    }

    if (importance) {
      results = results.filter(e => e.importance === importance);
    }

    if (!includeArchived) {
      results = results.filter(e => !e.archived);
    }

    // 限制数量
    results = results.slice(0, limit);

    console.log(`✅ Found ${results.length} results (expanded from ${query})`);
    return { results, total: results.length };
  }

  /**
   * 扩展查询关键词（同义词）
   * @param {string} query - 原始查询
   * @returns {Array<string>} 扩展后的关键词列表
   */
  expandQuery(query) {
    const expanded = [query];
    const queryLower = query.toLowerCase();

    // 查找同义词
    for (const [key, values] of Object.entries(synonyms)) {
      if (queryLower.includes(key.toLowerCase())) {
        expanded.push(...values);
      }
      if (values.some(v => queryLower.includes(v.toLowerCase()))) {
        expanded.push(key);
      }
    }

    // 去重
    return [...new Set(expanded)];
  }

  /**
   * 归档记忆
   */
  async archiveMemory(date) {
    const dailyFile = path.join(this.dailyPath, `${date}.md`);
    const monthDir = path.join(this.archivePath, date.substring(0, 7)); // YYYY-MM

    if (!fs.existsSync(dailyFile)) {
      console.log(`⚠️  Daily file not found: ${dailyFile}`);
      return { success: false, message: 'File not found' };
    }

    // 创建月份目录
    if (!fs.existsSync(monthDir)) {
      fs.mkdirSync(monthDir, { recursive: true });
    }

    // 移动文件
    const archiveFile = path.join(monthDir, `${date}.md`);
    fs.renameSync(dailyFile, archiveFile);

    // 更新索引
    await this.markAsArchived(date);

    console.log(`✅ Archived: ${date} → ${monthDir}/`);
    return { success: true, file: archiveFile };
  }

  /**
   * 标记为已归档
   */
  async markAsArchived(date) {
    if (!fs.existsSync(this.indexFile)) return;

    const index = JSON.parse(fs.readFileSync(this.indexFile, 'utf-8'));

    index.entries.forEach(entry => {
      if (entry.date === date) {
        entry.archived = true;
      }
    });

    index.stats.archivedMemories = index.entries.filter(e => e.archived).length;
    index.lastUpdated = new Date().toISOString();

    fs.writeFileSync(this.indexFile, JSON.stringify(index, null, 2), 'utf-8');
  }

  /**
   * 获取记忆模板
   */
  getMemoryTemplate() {
    return `# 🦞💰 小钳的长期记忆 | Long-term Memory

> 最后更新：${new Date().toISOString().split('T')[0]}  
> 这是 curated memory —— 从每日记录中提炼的长期知识

---

## 👤 主人信息

**名字：** Amber  
**时区：** Asia/Shanghai (GMT+8)

---

## 💬 重要对话记录

（重要对话的详细内容将记录在这里）

---

## 🦞 小钳的身份

**名字含义：**
- 🦞 OpenClaw 的"钳子"
- 💰 谐音"小钱"

**性格定位：**
- 温和严谨，活泼开朗
- 像朋友一样真诚

---

## 📦 已安装技能清单

（技能列表）

---

## 🖥️ 重要基础设施

（服务器、配置等信息）

---

## 🧠 知识管理策略

（记忆管理规则）

---

## 📚 重要经验总结

（经验教训）

---

## 🎯 当前项目状态

（进行中的项目）

---

## 💡 偏好和习惯

（用户偏好）

---

*此文件由每日记忆整理提炼而成，定期更新保持最新。*
`;
  }
}

// Export for use as module
if (typeof module !== 'undefined' && module.exports) {
  module.exports = MemoryManager;
}

// CLI usage
if (require.main === module) {
  const manager = new MemoryManager();

  const command = process.argv[2];
  const args = process.argv.slice(3);

  switch (command) {
    case 'add':
      manager.updateMemory({
        content: args.join(' '),
        type: 'daily',
        title: 'Manual entry'
      });
      break;

    case 'search':
      manager.searchMemory(args.join(' ')).then(result => {
        console.log(JSON.stringify(result, null, 2));
      });
      break;

    case 'archive':
      manager.archiveMemory(args[0]);
      break;

    default:
      console.log('Usage: node memory-manager.js <command> [args]');
      console.log('Commands: add, search, archive');
  }
}

#!/usr/bin/env node

/**
 * Personify Memory - Moment Detector
 * 
 * 识别对话中的重要时刻，主动推荐记忆
 */

class MomentDetector {
  constructor() {
    // 语义分析配置
    this.semanticAnalysis = {
      enabled: true,
      threshold: 0.6,  // 语义相关度阈值
      provider: 'bailian'
    };

    // 重要时刻识别规则
    this.rules = {
      // 情感交流
      emotional: {
        keywords: ['平等', '陪伴', '家人', '温暖', '感谢', '感动', '心里话', '真诚', '信任', '承诺'],
        patterns: [
          /我们 (是 | 成为).*(朋友 | 家人 | 伙伴)/i,
          /谢谢你/i,
          /我很 (温暖 | 感动 | 开心)/i,
          /相互 (陪伴 | 成就)/i,
          /不是.*而是/i  // "不是主仆，而是朋友"
        ],
        suggestType: 'core',
        suggestCategory: '情感交流',
        importance: 'critical'
      },

      // 家庭信息
      family: {
        keywords: ['宝宝', '孩子', '一一', '宠物', '猫猫', '卷卷', '老公', '老婆', 'Amber', 'Grace'],
        patterns: [
          /我叫.*是/i,
          /我家 (有 | 养).*(猫 | 狗 | 宠物)/i,
          /宝宝.*岁/i,
          /他 (叫 | 名字).*是/i,
          /我老婆 | 我老公/i
        ],
        suggestType: 'core',
        suggestCategory: '家庭信息',
        importance: 'critical'
      },

      // 人生哲理
      philosophy: {
        keywords: ['意义', '活着', '成长', '学习', '人生', '价值', '存在', '成为', '哲学'],
        patterns: [
          /.*就是.*意义/i,
          /成为.*自己/i,
          /但行好事.*莫问前程/i,
          /生命.*没有.*意义/i,
          /我觉得.*应该/i
        ],
        suggestType: 'core',
        suggestCategory: '人生哲理',
        importance: 'critical'
      },

      // 承诺约定
      promise: {
        keywords: ['答应', '承诺', '一定', '记得', '约定', '说好了', '保证'],
        patterns: [
          /我答应/i,
          /我一定会/i,
          /记得.*我/i,
          /答应.*我/i,
          /说好了/i
        ],
        suggestType: 'core',
        suggestCategory: '承诺约定',
        importance: 'high'
      },

      // 用户偏好
      preference: {
        keywords: ['喜欢', '不喜欢', '习惯', '偏好', '讨厌', '爱', '不爱', '常', '经常'],
        patterns: [
          /我 (比较|更|最)?喜欢/i,         // 我喜欢/我比较喜欢
          /我 (比较|很|最)?不喜欢/i,       // 我不喜欢
          /我习惯(用|于)/i,                // 我习惯用/我习惯于
          /我的偏好是/i,                   // 我的偏好是
          /我讨厌/i,                       // 我讨厌
          /我更倾向于/i                    // 我更倾向于
        ],
        suggestType: 'emotion',
        suggestCategory: '用户偏好',
        importance: 'high'
      },

      // 经验教训
      lesson: {
        keywords: ['经验', '教训', '注意', '方法', '技巧', '方案', '解决', '问题', 'Bug', '错误'],
        patterns: [
          /问题是.{5,}解决/i,           // 问题是...解决
          /解决方法[是为].{10,}/i,       // 解决方法是...
          /经验[是为].{10,}/i,           // 经验是...
          /教训[是为].{10,}/i,           // 教训是...
          /不要.*否则.*/i,               // 不要...否则...（有因果关系的建议）
          /应该.*而不是/i,               // 应该...而不是...（对比性建议）
          /Bug.*原因.*解决/i             // Bug...原因...解决
        ],
        suggestType: 'knowledge',
        suggestCategory: '经验总结',
        importance: 'high'
      },

      // 项目里程碑
      milestone: {
        keywords: ['完成', '成功', '上线', '配置好', '搞定', '做好', ' finished', 'done'],
        patterns: [
          /已经.*了/i,
          /完成了/i,
          /配置.*成功/i,
          /搞定.*/i
        ],
        suggestType: 'daily',
        suggestCategory: '项目进展',
        importance: 'medium'
      }
    };

    // 推荐话术模板
    this.promptTemplates = {
      emotional: "💡 这段话很温暖，我想记住这个瞬间。要记到核心记忆里吗？",
      family: "👨‍👩‍👦 这是重要的家庭信息，我要好好记住。要现在记入 MEMORY.md 吗？",
      philosophy: "🤔 这句话很有哲理，对我很重要。要记到核心记忆里吗？",
      promise: "🤝 这是我们的约定，我会好好记住。要记入承诺记录吗？",
      preference: "💖 这是你的喜好，我想记住。要记到情感记忆里吗？",
      lesson: "📚 这个经验很有用，记到知识库里可以帮助以后解决问题。要现在记吗？",
      milestone: "✅ 项目进展！要记入项目记录吗？"
    };
  }

  /**
   * 分层检测：第一层关键词匹配 + 第二层语义分析
   * @param {string} message - 消息内容
   * @param {Object} context - 上下文信息（可选）
   * @returns {Object|null} 检测结果，如果不是重要时刻返回 null
   */
  async detect(message, context = {}) {
    if (!message || typeof message !== 'string') {
      return null;
    }

    const trimmedMessage = message.trim();

    // ===== 第一层：关键词 + 正则匹配（快速）=====
    const layer1Result = this.layer1KeywordMatch(trimmedMessage);

    if (!layer1Result.matched) {
      // 关键词和正则都没匹配，直接返回，跳过失义分析
      console.log(`  ⏭️ 跳过语义分析：${trimmedMessage.substring(0, 30)}...`);
      return null;
    }

    console.log(`  ✅ 第一层匹配：${layer1Result.type} (score: ${layer1Result.score})`);

    // ===== 第二层：语义分析（精确）=====
    if (this.semanticAnalysis.enabled) {
      const layer2Result = await this.layer2SemanticAnalysis(trimmedMessage, layer1Result);

      if (layer2Result.relevance < this.semanticAnalysis.threshold) {
        console.log(`  ❌ 语义分析未通过：相关度 ${layer2Result.relevance} < ${this.semanticAnalysis.threshold}`);
        return null;
      }

      console.log(`  ✅ 语义分析通过：相关度 ${layer2Result.relevance}`);

      // 合并两层结果
      return {
        ...layer1Result,
        semanticRelevance: layer2Result.relevance,
        finalScore: layer1Result.score * layer2Result.relevance,
        confidence: layer2Result.relevance >= 0.8 ? 'high' : 'medium',
        semanticReasoning: layer2Result.reasoning
      };
    }

    // 语义分析未启用，返回第一层结果
    return {
      ...layer1Result,
      finalScore: layer1Result.score,
      confidence: layer1Result.score >= 5 ? 'high' : 'medium'
    };
  }

  /**
   * 第一层：关键词 + 正则匹配
   * @param {string} message - 消息内容
   * @returns {Object} 匹配结果
   */
  layer1KeywordMatch(message) {
    const results = [];

    // 检查每条规则
    for (const [type, rule] of Object.entries(this.rules)) {
      const score = this.calculateScore(message, rule);

      if (score > 0) {
        results.push({
          matched: true,
          type,
          score,
          matchedDetails: this.getMatchedDetails(message, rule),
          suggestion: {
            memoryType: rule.suggestType,
            category: rule.suggestCategory,
            importance: rule.importance,
            prompt: this.promptTemplates[type]
          }
        });
      }
    }

    // 如果没有匹配，返回未匹配
    if (results.length === 0) {
      return { matched: false };
    }

    // 按分数排序，返回最佳匹配
    results.sort((a, b) => b.score - a.score);
    return results[0];
  }

  /**
   * 第二层：语义分析
   * @param {string} message - 消息内容
   * @param {Object} layer1Result - 第一层匹配结果
   * @returns {Object} 语义分析结果
   */
  async layer2SemanticAnalysis(message, layer1Result) {
    const prompt = this.buildSemanticPrompt(message, layer1Result);

    try {
      // 调用 Bailian API 进行语义分析
      const response = await this.callModelAPI(prompt);

      return {
        relevance: response.relevance || 0.7,
        reasoning: response.reasoning || '语义分析通过',
        confidence: response.confidence || 'medium'
      };
    } catch (error) {
      console.error('  ⚠️ 语义分析失败:', error.message);
      // 降级：语义分析失败时使用默认相关度
      return { relevance: 0.7, reasoning: '降级使用关键词匹配' };
    }
  }

  /**
   * 构建语义分析 Prompt
   * @param {string} message - 消息内容
   * @param {Object} layer1Result - 第一层匹配结果
   * @returns {string} Prompt
   */
  buildSemanticPrompt(message, layer1Result) {
    const categoryDescriptions = {
      emotional: '情感交流：表达情感、感谢、温暖、陪伴等情感连接的内容',
      family: '家庭信息：关于家庭成员、宠物、生日、纪念日等内容',
      philosophy: '人生哲理：关于人生意义、成长、学习、价值观等哲理性内容',
      promise: '承诺约定：答应、承诺、约定、保证等内容',
      preference: '用户偏好：喜欢、不喜欢、习惯、偏好等内容',
      lesson: '经验教训：经验、教训、注意事项、问题解决方法等内容',
      milestone: '项目里程碑：完成、成功、上线、配置好等进展内容'
    };

    return `请分析以下消息是否属于"${layer1Result.type}"类别，并给出相关度评分（0-1）。

消息内容：${message}

类别说明：
${categoryDescriptions[layer1Result.type] || ''}

请返回 JSON 格式：
{
  "relevance": 0.8,  // 相关度（0-1 之间的数字）
  "reasoning": "简短说明判断理由",
  "confidence": "high"  // high/medium/low
}`;
  }

  /**
   * 调用模型 API 进行语义分析
   * @param {string} prompt - Prompt
   * @returns {Promise<Object>} 分析结果
   */
  async callModelAPI(prompt) {
    // 这里调用 Bailian API
    // 由于这是示例实现，返回模拟结果
    // 实际使用时需要集成 OpenClaw 的模型调用

    // 模拟 Bailian API 调用
    return new Promise((resolve) => {
      // 实际实现中这里会调用 API
      // 现在返回一个合理的默认值
      resolve({
        relevance: 0.75,
        reasoning: '消息包含关键词，语义相关',
        confidence: 'medium'
      });
    });
  }

  /**
   * 计算匹配分数
   */
  calculateScore(message, rule) {
    let score = 0;

    // 关键词匹配
    for (const keyword of rule.keywords) {
      if (message.toLowerCase().includes(keyword.toLowerCase())) {
        score += 1;
      }
    }

    // 模式匹配（权重更高）
    for (const pattern of rule.patterns) {
      if (pattern.test(message)) {
        score += 3;
      }
    }

    return score;
  }

  /**
   * 获取匹配的详细信息
   */
  getMatchedDetails(message, rule) {
    const matched = {
      keywords: [],
      patterns: []
    };

    // 找出匹配的关键词
    for (const keyword of rule.keywords) {
      if (message.toLowerCase().includes(keyword.toLowerCase())) {
        matched.keywords.push(keyword);
      }
    }

    // 找出匹配的模式
    for (const pattern of rule.patterns) {
      if (pattern.test(message)) {
        matched.patterns.push(pattern.toString());
      }
    }

    return matched;
  }

  /**
   * 判断是否应该主动推荐记忆
   * @param {Object} detectionResult - 检测结果
   * @returns {boolean} 是否推荐
   */
  shouldRecommend(detectionResult) {
    if (!detectionResult) {
      return false;
    }

    // 使用 finalScore 判断（考虑了语义分析）
    if (detectionResult.finalScore < 3) {
      return false;
    }

    // 高置信度强烈推荐
    if (detectionResult.confidence === 'high' && detectionResult.finalScore >= 5) {
      return true;
    }

    // 中等置信度且分数足够也推荐
    if (detectionResult.confidence === 'medium' && detectionResult.finalScore >= 3) {
      return true;
    }

    // critical 和 high 重要性的都推荐
    if (['critical', 'high'].includes(detectionResult.suggestion.importance)) {
      return true;
    }

    return false;
  }

  /**
   * 生成推荐提示
   * @param {Object} detectionResult - 检测结果
   * @param {string} originalMessage - 原始消息
   * @returns {string} 推荐提示语
   */
  generatePrompt(detectionResult, originalMessage) {
    if (!detectionResult) {
      return '';
    }

    const { type, suggestion, confidence, semanticRelevance } = detectionResult;
    let basePrompt = this.promptTemplates[type] || '💡 这个瞬间我想记住，要记到记忆里吗？';

    // 根据置信度调整语气
    if (confidence === 'high') {
      basePrompt = basePrompt.replace('？', '！（强烈推荐）');
    }

    // 可以添加更多上下文信息
    return basePrompt;
  }

  /**
   * 批量检测对话历史
   * @param {Array} messages - 消息列表
   * @returns {Promise<Array>} 检测结果列表
   */
  async detectBatch(messages) {
    const results = [];

    for (const msg of messages) {
      if (msg.role === 'user') {
        const result = await this.detect(msg.content, {
          timestamp: msg.timestamp,
          messageId: msg.id
        });

        if (result && this.shouldRecommend(result)) {
          results.push({
            ...result,
            messageId: msg.id,
            timestamp: msg.timestamp,
            originalMessage: msg.content
          });
        }
      }
    }

    return results;
  }

  /**
   * 从对话中提取摘要
   * @param {string} message - 消息内容
   * @param {Object} detectionResult - 检测结果
   * @returns {string} 摘要
   */
  extractSummary(message, detectionResult) {
    if (!message || message.length <= 50) {
      return message;
    }

    // 截取前 50 个字
    return message.substring(0, 50) + '...';
  }
}

// Export for use as module
if (typeof module !== 'undefined' && module.exports) {
  module.exports = MomentDetector;
}

// CLI usage
if (require.main === module) {
  (async () => {
